const readline = require('readline');

const rl = readline.createInterface({
  input: process.stdin,
  output: process.stdout
});

rl.on('line', (line) => {
  const [m, b] = line.trim().split(/\s+/).map(Number);
  let maxBananas = 0;

  for (let y = 0; y <= b; y++) {
    const xMax = m * (b - y);
    // sum_x from 0 to xMax of (x + y)
    // = sum_x x + sum_x y
    // = xMax*(xMax+1)/2 + y*(xMax+1)
    const sumX = xMax * (xMax + 1) / 2;
    const sumY = y * (xMax + 1);
    const total = sumX + sumY;
    if (total > maxBananas) maxBananas = total;
  }

  console.log(maxBananas);
  rl.close();
});
